INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'pork-vindaloo'), 1, 'Soak Kashmiri chillies in warm vinegar for 20 minutes, then grind with garlic, ginger, cumin, peppercorns, cloves, cinnamon, and turmeric into a smooth paste.', 'कश्मीरी मिर्च को गर्म सिरके में 20 मिनट भिगोएं, फिर लहसुन, अदरक, जीरा, काली मिर्च, लौंग, दालचीनी और हल्दी के साथ बारीक पीस लें।', 'काश्मिरी मिरच्या कोमट व्हिनेगरमध्ये 20 मिनिटे भिजवा, नंतर लसूण, आले, जिरे, काळी मिरी, लवंग, दालचिनी आणि हळदीसह बारीक वाटून घ्या.', 25);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'pork-vindaloo'), 2, 'Marinate pork pieces in this paste for at least 30 minutes, preferably overnight.', 'पोर्क के टुकड़ों को इस पेस्ट में कम से कम 30 मिनट, अच्छा हो तो रात भर मैरिनेट करें।', 'डुकराच्या मांसाचे तुकडे या पेस्टमध्ये किमान 30 मिनिटे, शक्यतो रात्रभर मॅरिनेट करा.', 30);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'pork-vindaloo'), 3, 'Heat oil in a heavy pan, sauté sliced onions until deep golden brown.', 'भारी पैन में तेल गरम करें, कटे हुए प्याज़ को गहरा सुनहरा होने तक भूनें।', 'जड बुडाच्या पॅनमध्ये तेल गरम करा, कापलेला कांदा गडद सोनेरी होईपर्यंत परतून घ्या.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'pork-vindaloo'), 4, 'Add the marinated pork with all the paste and sear on high heat for 5 minutes.', 'मैरिनेट किया हुआ पोर्क सारे पेस्ट सहित डालें और तेज़ आंच पर 5 मिनट भूनें।', 'मॅरिनेट केलेले मांस सर्व पेस्टसह घाला आणि मोठ्या आचेवर 5 मिनिटे परतून घ्या.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'pork-vindaloo'), 5, 'Add water just to cover, bring to a boil, then simmer covered on low heat until pork is fork-tender.', 'बस इतना पानी डालें कि मांस डूब जाए, उबाल आने दें, फिर ढककर धीमी आंच पर पकाएं जब तक मांस नरम न हो जाए।', 'मांस बुडेल एवढे पाणी घाला, उकळी आणा, नंतर झाकण ठेवून मंद आचेवर मांस मऊ होईपर्यंत शिजवा.', 45);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'pork-vindaloo'), 6, 'Add jaggery, adjust salt and vinegar to balance the sweet-sour-spicy flavours. Simmer uncovered to thicken the gravy.', 'गुड़ डालें, नमक और सिरका डालकर खट्टे-मीठे-तीखे स्वाद का संतुलन बनाएं। ग्रेवी गाढ़ी करने के लिए बिना ढके पकाएं।', 'गूळ घाला, मीठ आणि व्हिनेगर घालून आंबट-गोड-तिखट चवीचा समतोल साधा. रस्सा आटवण्यासाठी झाकण काढून शिजवा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chicken-xacuti'), 1, 'Dry roast grated coconut, coriander seeds, poppy seeds, red chillies, star anise, cloves, peppercorns, and nutmeg until fragrant and lightly browned.', 'कसा नारियल, धनिया, खसखस, लाल मिर्च, चक्र फूल, लौंग, काली मिर्च और जायफल को सूखा भून लें जब तक खुशबू आए और हल्का भूरा हो जाए।', 'खोबरे, धणे, खसखस, लाल मिरच्या, बाद्यान, लवंग, काळी मिरी आणि जायफळ सुगंध येईपर्यंत आणि हलके तपकिरी होईपर्यंत कोरडे भाजा.', 8);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chicken-xacuti'), 2, 'Cool the roasted spices and grind into a fine paste with a little water.', 'भुने मसाले ठंडे करें और थोड़ा पानी डालकर बारीक पेस्ट बना लें।', 'भाजलेले मसाले थंड करा आणि थोडे पाणी घालून बारीक वाटून घ्या.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chicken-xacuti'), 3, 'Heat oil, sauté sliced onions until golden. Add turmeric and the ground spice paste, cook until oil separates.', 'तेल गरम करें, कटे प्याज़ सुनहरा होने तक भूनें। हल्दी और पीसा मसाला पेस्ट डालकर तेल छूटने तक पकाएं।', 'तेल गरम करा, कापलेला कांदा सोनेरी होईपर्यंत परता. हळद आणि वाटलेला मसाला घालून तेल सुटेपर्यंत शिजवा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chicken-xacuti'), 4, 'Add chicken pieces, sear well on all sides for 5 minutes.', 'चिकन के टुकड़े डालें, सभी तरफ से 5 मिनट अच्छे से भूनें।', 'चिकनचे तुकडे घाला, सर्व बाजूंनी 5 मिनिटे नीट परतून घ्या.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chicken-xacuti'), 5, 'Add water, tamarind pulp, and salt. Cover and cook on low heat until chicken is tender and gravy thickens.', 'पानी, इमली का गूदा और नमक डालें। ढककर धीमी आंच पर पकाएं जब तक चिकन नरम हो और ग्रेवी गाढ़ी हो जाए।', 'पाणी, चिंचेचा कोळ आणि मीठ घाला. झाकण ठेवून मंद आचेवर चिकन मऊ होईपर्यंत आणि रस्सा आटेपर्यंत शिजवा.', 30);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chicken-xacuti'), 6, 'Adjust seasoning and serve hot with steamed rice.', 'चाशनी ठीक करें और गरमागरम चावल के साथ परोसें।', 'चव पाहून मीठ-मसाला ठीक करा आणि गरम भातासोबत वाढा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'fish-recheado'), 1, 'Clean the fish, make deep slits on both sides. Rub with turmeric and salt, set aside.', 'मछली साफ़ करें, दोनों तरफ गहरे चीरे लगाएं। हल्दी और नमक लगाकर रख दें।', 'मासा स्वच्छ करा, दोन्ही बाजूला खोल चिरे द्या. हळद आणि मीठ लावून बाजूला ठेवा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'fish-recheado'), 2, 'Soak red chillies in vinegar for 15 minutes. Grind with garlic, ginger, cumin, peppercorns, cloves, and sugar into a thick paste.', 'लाल मिर्च को सिरके में 15 मिनट भिगोएं। लहसुन, अदरक, जीरा, काली मिर्च, लौंग और चीनी के साथ गाढ़ा पेस्ट बनाएं।', 'लाल मिरच्या व्हिनेगरमध्ये 15 मिनिटे भिजवा. लसूण, आले, जिरे, काळी मिरी, लवंग आणि साखरेसह जाड पेस्ट वाटा.', 18);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'fish-recheado'), 3, 'Stuff the recheado paste generously into the slits and cavity of the fish. Let it marinate for 15 minutes.', 'रेचियाड पेस्ट को मछली के चीरों और अंदर भरपूर भरें। 15 मिनट मैरिनेट होने दें।', 'रेशाद मसाला माशाच्या चिरांमध्ये आणि पोटात भरपूर भरा. 15 मिनिटे मॅरिनेट होऊ द्या.', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'fish-recheado'), 4, 'Heat oil in a flat pan on medium heat. Place the fish and shallow-fry for 5-6 minutes on each side until crisp and cooked through.', 'सपाट पैन में मध्यम आंच पर तेल गरम करें। मछली रखें और हर तरफ 5-6 मिनट कुरकुरा और पक जाने तक तलें।', 'सपाट तव्यावर मध्यम आचेवर तेल गरम करा. मासा ठेवा आणि दोन्ही बाजूंनी 5-6 मिनिटे कुरकुरीत होईपर्यंत तळा.', 12);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'fish-recheado'), 5, 'Serve hot with a squeeze of lime and steamed rice.', 'गरमागरम लिंबू निचोड़कर चावल के साथ परोसें।', 'गरम असताना लिंबू पिळून भातासोबत वाढा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ros-omelette'), 1, 'For ros gravy: grind grated coconut with a little water into a smooth paste. Set aside.', 'रॉस ग्रेवी के लिए: कसे नारियल को थोड़े पानी के साथ बारीक पेस्ट बनाएं। अलग रखें।', 'रॉस ग्रेव्हीसाठी: किसलेले खोबरे थोड्या पाण्यासह बारीक वाटून घ्या. बाजूला ठेवा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ros-omelette'), 2, 'Heat oil, sauté half the chopped onion until soft. Add tomato, red chilli powder, turmeric, coriander powder, and salt. Cook until tomatoes break down.', 'तेल गरम करें, आधा कटा प्याज़ नरम होने तक भूनें। टमाटर, लाल मिर्च पाउडर, हल्दी, धनिया पाउडर और नमक डालें। टमाटर गलने तक पकाएं।', 'तेल गरम करा, अर्धा चिरलेला कांदा मऊ होईपर्यंत परता. टोमॅटो, लाल मिरची पावडर, हळद, धणे पावडर आणि मीठ घाला. टोमॅटो गळेपर्यंत शिजवा.', 7);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ros-omelette'), 3, 'Add coconut paste and water to make a thick gravy. Simmer for 5 minutes. This is the ros.', 'नारियल का पेस्ट और पानी डालकर गाढ़ी ग्रेवी बनाएं। 5 मिनट उबालें। यही रॉस है।', 'नारळाची पेस्ट आणि पाणी घालून घट्ट ग्रेव्ही बनवा. 5 मिनिटे उकळा. हीच रॉस ग्रेव्ही.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ros-omelette'), 4, 'Beat eggs with remaining onion, green chillies, and salt. Make fluffy omelettes in butter on a hot tawa.', 'अंडों को बचे प्याज़, हरी मिर्च और नमक के साथ फेंटें। गर्म तवे पर मक्खन में फूले हुए ऑमलेट बनाएं।', 'अंडी उरलेला कांदा, हिरव्या मिरच्या आणि मीठ घालून फेटा. गरम तव्यावर बटरमध्ये फुलके ऑम्लेट बनवा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ros-omelette'), 5, 'Pour hot ros gravy over the omelettes, toast pav in butter, and serve immediately.', 'ऑमलेट पर गरम रॉस ग्रेवी डालें, पाव को मक्खन में सेकें और तुरंत परोसें।', 'ऑम्लेटवर गरम रॉस ग्रेव्ही ओता, पाव बटरमध्ये भाजा आणि लगेच वाढा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'prawn-balchao'), 1, 'Soak red chillies in vinegar for 15 minutes. Grind with garlic, ginger, cumin, and peppercorns into a paste.', 'लाल मिर्च को सिरके में 15 मिनट भिगोएं। लहसुन, अदरक, जीरा और काली मिर्च के साथ पेस्ट बना लें।', 'लाल मिरच्या व्हिनेगरमध्ये 15 मिनिटे भिजवा. लसूण, आले, जिरे आणि काळी मिरीसह पेस्ट वाटा.', 18);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'prawn-balchao'), 2, 'Heat oil, fry prawns lightly with turmeric and salt until just pink. Remove and set aside.', 'तेल गरम करें, झींगा को हल्दी और नमक के साथ हल्का गुलाबी होने तक तलें। निकालकर रख दें।', 'तेल गरम करा, कोळंबी हळद आणि मीठ घालून हलकी गुलाबी होईपर्यंत तळा. काढून बाजूला ठेवा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'prawn-balchao'), 3, 'In the same oil, sauté chopped onions until soft. Add the ground masala paste and cook until oil separates.', 'उसी तेल में कटे प्याज़ नरम होने तक भूनें। पीसा मसाला पेस्ट डालकर तेल छूटने तक पकाएं।', 'त्याच तेलात चिरलेला कांदा मऊ होईपर्यंत परता. वाटलेला मसाला घालून तेल सुटेपर्यंत शिजवा.', 8);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'prawn-balchao'), 4, 'Add chopped tomatoes and cook until they turn mushy and blend into the masala.', 'कटे टमाटर डालें और गलकर मसाले में मिल जाने तक पकाएं।', 'चिरलेले टोमॅटो घाला आणि ते गळून मसाल्यात मिसळेपर्यंत शिजवा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'prawn-balchao'), 5, 'Add fried prawns, sugar, and remaining vinegar. Cook for 3-4 minutes on low heat. Adjust salt.', 'तले हुए झींगा, चीनी और बचा सिरका डालें। धीमी आंच पर 3-4 मिनट पकाएं। नमक ठीक करें।', 'तळलेली कोळंबी, साखर आणि उरलेले व्हिनेगर घाला. मंद आचेवर 3-4 मिनिटे शिजवा. मीठ चवीनुसार घाला.', 4);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'prawn-balchao'), 6, 'Let it rest for 30 minutes before serving — balchao tastes better the next day.', 'परोसने से पहले 30 मिनट रखें — बालचाओ अगले दिन और स्वादिष्ट लगता है।', 'वाढण्यापूर्वी 30 मिनिटे ठेवा — बालचाव दुसऱ्या दिवशी अजून चविष्ट लागतो.', 30);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'goan-fish-curry-rice'), 1, 'Grind grated coconut, red chillies, coriander seeds, garlic, and turmeric with a little water into a smooth paste.', 'कसा नारियल, लाल मिर्च, धनिया, लहसुन और हल्दी को थोड़े पानी के साथ बारीक पेस्ट बना लें।', 'किसलेले खोबरे, लाल मिरच्या, धणे, लसूण आणि हळद थोड्या पाण्यासह बारीक वाटून घ्या.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'goan-fish-curry-rice'), 2, 'Heat oil, sauté sliced onion and green chillies until onion softens.', 'तेल गरम करें, कटा प्याज़ और हरी मिर्च प्याज़ नरम होने तक भूनें।', 'तेल गरम करा, कापलेला कांदा आणि हिरव्या मिरच्या कांदा मऊ होईपर्यंत परता.', 4);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'goan-fish-curry-rice'), 3, 'Add the coconut paste and 2 cups of water. Add kokum and tamarind. Bring to a boil and simmer for 10 minutes.', 'नारियल का पेस्ट और 2 कप पानी डालें। कोकम और इमली डालें। उबाल आने दें और 10 मिनट पकाएं।', 'नारळाची पेस्ट आणि 2 कप पाणी घाला. कोकम आणि चिंच घाला. उकळी आणून 10 मिनिटे शिजवा.', 12);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'goan-fish-curry-rice'), 4, 'Slide in the fish pieces gently, add salt. Cook on low heat for 8-10 minutes without stirring — just shake the pan.', 'मछली के टुकड़े धीरे से डालें, नमक डालें। धीमी आंच पर 8-10 मिनट बिना हिलाए पकाएं — बस पैन हिलाएं।', 'माशाचे तुकडे हळूवारपणे सोडा, मीठ घाला. मंद आचेवर 8-10 मिनिटे न ढवळता शिजवा — फक्त पॅन हलवा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'goan-fish-curry-rice'), 5, 'Let it rest for 5 minutes. Serve hot with steamed rice.', '5 मिनट रखें। गरमागरम चावल के साथ परोसें।', '5 मिनिटे ठेवा. गरम भातासोबत वाढा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'sorpotel'), 1, 'Boil pork and liver in salted water until cooked through. Reserve the stock. Cut meat into small cubes.', 'पोर्क और कलेजी को नमकीन पानी में पकने तक उबालें। शोरबा बचाकर रखें। मांस को छोटे टुकड़ों में काटें।', 'डुकराचे मांस आणि काळजी मिठाच्या पाण्यात शिजवा. रस्सा बाजूला ठेवा. मांस लहान तुकड्यांत कापा.', 30);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'sorpotel'), 2, 'Soak red chillies in vinegar. Grind with garlic, ginger, cumin, cloves, cinnamon, peppercorns, and turmeric.', 'लाल मिर्च को सिरके में भिगोएं। लहसुन, अदरक, जीरा, लौंग, दालचीनी, काली मिर्च और हल्दी के साथ पीसें।', 'लाल मिरच्या व्हिनेगरमध्ये भिजवा. लसूण, आले, जिरे, लवंग, दालचिनी, काळी मिरी आणि हळदीसह वाटा.', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'sorpotel'), 3, 'Heat oil, sauté chopped onions until dark brown. Add the ground masala paste and fry until oil separates.', 'तेल गरम करें, कटे प्याज़ गहरा भूरा होने तक भूनें। पीसा मसाला डालकर तेल छूटने तक भूनें।', 'तेल गरम करा, चिरलेला कांदा गडद तपकिरी होईपर्यंत परता. वाटलेला मसाला घालून तेल सुटेपर्यंत परता.', 12);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'sorpotel'), 4, 'Add the cubed pork and liver. Fry on high heat for 5 minutes to sear the meat.', 'कटा पोर्क और कलेजी डालें। तेज़ आंच पर 5 मिनट भूनें।', 'कापलेले मांस आणि काळजी घाला. मोठ्या आचेवर 5 मिनिटे परता.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'sorpotel'), 5, 'Add reserved stock, remaining vinegar, and jaggery. Simmer on low heat for 30-40 minutes until thick and oily.', 'बचा हुआ शोरबा, बाकी सिरका और गुड़ डालें। धीमी आंच पर 30-40 मिनट गाढ़ा और तैलीय होने तक पकाएं।', 'बाजूला ठेवलेला रस्सा, उरलेले व्हिनेगर आणि गूळ घाला. मंद आचेवर 30-40 मिनिटे घट्ट आणि तेलकट होईपर्यंत शिजवा.', 35);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'sorpotel'), 6, 'Let it rest overnight for best flavour. Reheat and serve with pav or sannas.', 'सबसे अच्छे स्वाद के लिए रात भर रखें। गरम करके पाव या सन्नस के साथ परोसें।', 'उत्तम चवीसाठी रात्रभर ठेवा. गरम करून पाव किंवा सन्नासोबत वाढा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chicken-cafreal'), 1, 'Grind coriander leaves, green chillies, garlic, ginger, cumin, peppercorns, cloves, cinnamon, lime juice, and salt into a smooth green paste.', 'धनिया पत्ती, हरी मिर्च, लहसुन, अदरक, जीरा, काली मिर्च, लौंग, दालचीनी, नींबू रस और नमक का बारीक हरा पेस्ट बनाएं।', 'कोथिंबीर, हिरव्या मिरच्या, लसूण, आले, जिरे, काळी मिरी, लवंग, दालचिनी, लिंबाचा रस आणि मीठ एकत्र बारीक हिरवी पेस्ट वाटा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chicken-cafreal'), 2, 'Make deep cuts in chicken pieces. Rub the green paste all over and into the cuts. Marinate for at least 1 hour.', 'चिकन के टुकड़ों में गहरे चीरे लगाएं। हरा पेस्ट अच्छे से लगाएं। कम से कम 1 घंटे मैरिनेट करें।', 'चिकनच्या तुकड्यांना खोल चिरे द्या. हिरवी पेस्ट नीट लावा. किमान 1 तास मॅरिनेट करा.', 60);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chicken-cafreal'), 3, 'Heat oil in a heavy pan on medium heat. Place chicken pieces skin-side down and sear without moving for 7-8 minutes.', 'भारी पैन में मध्यम आंच पर तेल गरम करें। चिकन त्वचा वाली तरफ रखें और 7-8 मिनट बिना हिलाए सेक लें।', 'जड पॅनमध्ये मध्यम आचेवर तेल गरम करा. चिकन कातडीच्या बाजूने ठेवा आणि 7-8 मिनिटे न हलवता भाजा.', 8);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chicken-cafreal'), 4, 'Flip and cook the other side for 7-8 minutes. Then cover and cook on low heat until chicken is fully done.', 'पलटकर दूसरी तरफ 7-8 मिनट पकाएं। फिर ढककर धीमी आंच पर चिकन पूरा पकने तक पकाएं।', 'उलटून दुसऱ्या बाजूने 7-8 मिनिटे शिजवा. नंतर झाकण ठेवून मंद आचेवर चिकन पूर्ण शिजेपर्यंत शिजवा.', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chicken-cafreal'), 5, 'Serve hot with any remaining pan juices spooned over, along with rice or pav.', 'पैन में बचा रस ऊपर डालकर गरमागरम चावल या पाव के साथ परोसें।', 'पॅनमधील उरलेला रस वरून ओतून गरम भात किंवा पावासोबत वाढा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ambot-tik'), 1, 'Grind red chillies, garlic, cumin, peppercorns, and turmeric with a little water into a smooth paste.', 'लाल मिर्च, लहसुन, जीरा, काली मिर्च और हल्दी को थोड़े पानी के साथ बारीक पेस्ट बना लें।', 'लाल मिरच्या, लसूण, जिरे, काळी मिरी आणि हळद थोड्या पाण्यासह बारीक वाटा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ambot-tik'), 2, 'Heat oil, sauté sliced onion until translucent. Add chopped tomato and cook until soft.', 'तेल गरम करें, कटा प्याज़ पारदर्शी होने तक भूनें। कटा टमाटर डालकर नरम होने तक पकाएं।', 'तेल गरम करा, कापलेला कांदा पारदर्शक होईपर्यंत परता. चिरलेला टोमॅटो घालून मऊ होईपर्यंत शिजवा.', 7);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ambot-tik'), 3, 'Add the ground masala paste and fry for 3-4 minutes until fragrant.', 'पीसा मसाला पेस्ट डालकर 3-4 मिनट खुशबू आने तक भूनें।', 'वाटलेला मसाला घालून 3-4 मिनिटे सुगंध येईपर्यंत परता.', 4);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ambot-tik'), 4, 'Add 2 cups water, kokum, tamarind, and salt. Bring to a boil and simmer for 5 minutes.', '2 कप पानी, कोकम, इमली और नमक डालें। उबाल आने दें और 5 मिनट पकाएं।', '2 कप पाणी, कोकम, चिंच आणि मीठ घाला. उकळी आणून 5 मिनिटे शिजवा.', 6);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ambot-tik'), 5, 'Add fish pieces and cook gently on low heat for 8-10 minutes. Do not stir — shake the pan.', 'मछली के टुकड़े डालें और धीमी आंच पर 8-10 मिनट पकाएं। हिलाएं नहीं — पैन हिलाएं।', 'माशाचे तुकडे घाला आणि मंद आचेवर 8-10 मिनिटे शिजवा. ढवळू नका — पॅन हलवा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ambot-tik'), 6, 'Check seasoning and serve hot with plain rice.', 'चाशनी जांचें और सादे चावल के साथ गरमागरम परोसें।', 'चव तपासा आणि वरणभातासोबत गरम वाढा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'sorak'), 1, 'Grind grated coconut, red chillies, coriander seeds, garlic, and turmeric with water into a smooth paste.', 'कसा नारियल, लाल मिर्च, धनिया, लहसुन और हल्दी को पानी के साथ बारीक पेस्ट बना लें।', 'किसलेले खोबरे, लाल मिरच्या, धणे, लसूण आणि हळद पाण्यासह बारीक वाटून घ्या.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'sorak'), 2, 'Heat oil, add sliced onion and green chilli. Sauté until onion softens.', 'तेल गरम करें, कटा प्याज़ और हरी मिर्च डालें। प्याज़ नरम होने तक भूनें।', 'तेल गरम करा, कापलेला कांदा आणि हिरवी मिरची घाला. कांदा मऊ होईपर्यंत परता.', 4);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'sorak'), 3, 'Add the coconut paste and 2 cups of water. Add kokum and salt. Stir well.', 'नारियल का पेस्ट और 2 कप पानी डालें। कोकम और नमक डालें। अच्छे से मिलाएं।', 'नारळाची पेस्ट आणि 2 कप पाणी घाला. कोकम आणि मीठ घाला. नीट ढवळा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'sorak'), 4, 'Bring to a boil, then simmer on low heat for 10-12 minutes until the curry thickens slightly.', 'उबाल आने दें, फिर धीमी आंच पर 10-12 मिनट पकाएं जब तक करी थोड़ी गाढ़ी हो जाए।', 'उकळी आणा, नंतर मंद आचेवर 10-12 मिनिटे करी थोडी घट्ट होईपर्यंत शिजवा.', 12);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'sorak'), 5, 'Serve hot with steamed rice. This is typically eaten as a side curry.', 'गरमागरम चावल के साथ परोसें। यह आमतौर पर साइड करी के रूप में खाई जाती है।', 'गरम भातासोबत वाढा. ही साधारणपणे बाजूची करी म्हणून खाल्ली जाते.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'khatkhate'), 1, 'Soak chana dal for 30 minutes. Boil val (field beans) separately until half-cooked.', 'चना दाल 30 मिनट भिगोएं। वाल को अलग से आधा उबाल लें।', 'हरभरा डाळ 30 मिनिटे भिजवा. वाल वेगळे अर्धे शिजवा.', 30);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'khatkhate'), 2, 'Grind grated coconut, red chillies, coriander seeds, and cumin into a coarse paste.', 'कसा नारियल, लाल मिर्च, धनिया और जीरा का दरदरा पेस्ट बनाएं।', 'किसलेले खोबरे, लाल मिरच्या, धणे आणि जिरे जाडसर वाटून घ्या.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'khatkhate'), 3, 'Cut all vegetables into bite-sized pieces. Cook in water with turmeric and salt until just tender.', 'सब्ज़ियां छोटे टुकड़ों में काटें। हल्दी और नमक के साथ पानी में नरम होने तक पकाएं।', 'सर्व भाज्या लहान तुकड्यांत कापा. हळद आणि मीठ घालून पाण्यात मऊ होईपर्यंत शिजवा.', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'khatkhate'), 4, 'Add chana dal, val, the coconut paste, and kokum. Simmer for 10 minutes.', 'चना दाल, वाल, नारियल पेस्ट और कोकम डालें। 10 मिनट पकाएं।', 'हरभरा डाळ, वाल, नारळाची पेस्ट आणि कोकम घाला. 10 मिनिटे शिजवा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'khatkhate'), 5, 'Add jaggery, adjust salt. Do not stir too much — the vegetables should hold their shape.', 'गुड़ डालें, नमक ठीक करें। ज़्यादा न हिलाएं — सब्ज़ियां अपने आकार में रहनी चाहिए।', 'गूळ घाला, मीठ ठीक करा. खूप ढवळू नका — भाज्यांचा आकार टिकला पाहिजे.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'khatkhate'), 6, 'Serve warm with rice. Traditionally no oil or tempering is used in this dish.', 'गुनगुना चावल के साथ परोसें। परंपरागत रूप से इसमें तेल या तड़का नहीं लगाया जाता।', 'कोमट भातासोबत वाढा. पारंपरिकपणे या पदार्थात तेल किंवा फोडणी वापरत नाहीत.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mushroom-xacuti'), 1, 'Dry roast coconut, coriander seeds, poppy seeds, red chillies, star anise, cloves, and peppercorns until fragrant.', 'नारियल, धनिया, खसखस, लाल मिर्च, चक्र फूल, लौंग और काली मिर्च सूखा भून लें।', 'खोबरे, धणे, खसखस, लाल मिरच्या, बाद्यान, लवंग आणि काळी मिरी कोरडे भाजा.', 7);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mushroom-xacuti'), 2, 'Cool and grind into a fine paste with a little water.', 'ठंडा करके थोड़े पानी के साथ बारीक पेस्ट बना लें।', 'थंड करून थोड्या पाण्यासह बारीक वाटून घ्या.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mushroom-xacuti'), 3, 'Heat oil, sauté sliced onions until golden. Add turmeric and the ground paste. Cook until oil separates.', 'तेल गरम करें, कटे प्याज़ सुनहरे होने तक भूनें। हल्दी और पीसा पेस्ट डालकर तेल छूटने तक पकाएं।', 'तेल गरम करा, कापलेला कांदा सोनेरी होईपर्यंत परता. हळद आणि वाटलेला मसाला घालून तेल सुटेपर्यंत शिजवा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mushroom-xacuti'), 4, 'Add halved mushrooms and sauté for 3 minutes until they begin to release moisture.', 'आधे कटे मशरूम डालें और 3 मिनट भूनें जब तक पानी न छूटने लगे।', 'अर्ध्या कापलेले मशरूम घाला आणि 3 मिनिटे पाणी सुटायला लागेपर्यंत परता.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mushroom-xacuti'), 5, 'Add water for desired gravy consistency, tamarind, and salt. Simmer for 12-15 minutes.', 'मनचाही ग्रेवी के लिए पानी, इमली और नमक डालें। 12-15 मिनट पकाएं।', 'हव्या तेवढ्या रश्शासाठी पाणी, चिंच आणि मीठ घाला. 12-15 मिनिटे शिजवा.', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mushroom-xacuti'), 6, 'Serve hot with steamed rice or pav.', 'गरमागरम चावल या पाव के साथ परोसें।', 'गरम भात किंवा पावासोबत वाढा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'veg-xacuti'), 1, 'Dry roast coconut, coriander seeds, poppy seeds, red chillies, star anise, and cloves until golden and fragrant. Cool and grind to a fine paste.', 'नारियल, धनिया, खसखस, लाल मिर्च, चक्र फूल और लौंग सुनहरा और खुशबूदार होने तक सूखा भूनें। ठंडा करके बारीक पेस्ट बना लें।', 'खोबरे, धणे, खसखस, लाल मिरच्या, बाद्यान आणि लवंग सोनेरी आणि सुगंधी होईपर्यंत कोरडे भाजा. थंड करून बारीक वाटा.', 12);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'veg-xacuti'), 2, 'Cut potato and carrot into cubes, beans into 1-inch pieces. Boil until half-cooked. Drain.', 'आलू और गाजर के टुकड़े, बीन्स 1 इंच के टुकड़ों में काटें। आधा उबालें। पानी निकालें।', 'बटाटा आणि गाजर तुकड्यांत, फरसबी 1 इंच तुकड्यांत कापा. अर्धे शिजवा. पाणी काढा.', 8);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'veg-xacuti'), 3, 'Heat oil, sauté sliced onions until golden brown. Add turmeric and the ground xacuti paste. Cook until oil separates.', 'तेल गरम करें, कटे प्याज़ सुनहरे भूरे होने तक भूनें। हल्दी और शाकुती पेस्ट डालकर तेल छूटने तक पकाएं।', 'तेल गरम करा, कापलेला कांदा सोनेरी तपकिरी होईपर्यंत परता. हळद आणि शाकुती पेस्ट घालून तेल सुटेपर्यंत शिजवा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'veg-xacuti'), 4, 'Add the half-cooked vegetables and peas. Add water for gravy and salt. Cover and simmer for 12-15 minutes.', 'अर्ध-पकी सब्ज़ियां और मटर डालें। ग्रेवी के लिए पानी और नमक डालें। ढककर 12-15 मिनट पकाएं।', 'अर्धवट शिजवलेल्या भाज्या आणि वाटाणे घाला. रश्शासाठी पाणी आणि मीठ घाला. झाकण ठेवून 12-15 मिनिटे शिजवा.', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'veg-xacuti'), 5, 'Serve hot with steamed rice.', 'गरमागरम चावल के साथ परोसें।', 'गरम भातासोबत वाढा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'solachi-kadhi'), 1, 'Soak kokum in 1 cup warm water for 20 minutes. Squeeze and extract the deep pink liquid. Discard the kokum.', 'कोकम को 1 कप गुनगुने पानी में 20 मिनट भिगोएं। निचोड़कर गहरा गुलाबी पानी निकालें। कोकम फेंक दें।', 'कोकम 1 कप कोमट पाण्यात 20 मिनिटे भिजवा. पिळून गडद गुलाबी पाणी काढा. कोकम टाकून द्या.', 22);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'solachi-kadhi'), 2, 'Grind garlic, green chillies, and cumin into a paste.', 'लहसुन, हरी मिर्च और जीरे का पेस्ट बना लें।', 'लसूण, हिरव्या मिरच्या आणि जिरे वाटून पेस्ट करा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'solachi-kadhi'), 3, 'Mix coconut milk with the kokum extract. Add the garlic-chilli paste, sugar, and salt. Stir well.', 'नारियल दूध में कोकम का अर्क मिलाएं। लहसुन-मिर्च पेस्ट, चीनी और नमक डालें। अच्छे से मिलाएं।', 'नारळाच्या दुधात कोकमचा अर्क मिसळा. लसूण-मिरची पेस्ट, साखर आणि मीठ घाला. नीट ढवळा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'solachi-kadhi'), 4, 'If serving warm, heat gently without boiling — coconut milk splits at high heat.', 'गुनगुना परोसना हो तो धीरे-धीरे गरम करें, उबलने न दें — तेज़ आंच पर नारियल दूध फट जाता है।', 'कोमट वाढायचे असल्यास हळूहळू गरम करा, उकळू देऊ नका — मोठ्या आचेवर नारळाचे दूध फुटते.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'solachi-kadhi'), 5, 'Garnish with chopped coriander leaves. Serve as a drink or as a curry with rice.', 'कटा हरा धनिया छिड़कें। पेय के रूप में या चावल के साथ करी के रूप में परोसें।', 'चिरलेली कोथिंबीर घाला. पेय म्हणून किंवा भातासोबत करी म्हणून वाढा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'alsande'), 1, 'Pressure cook soaked black-eyed peas with turmeric and salt until soft (3-4 whistles).', 'भीगी लोबिया को हल्दी और नमक के साथ नरम होने तक प्रेशर कुक करें (3-4 सीटी)।', 'भिजवलेले अळसांदे हळद आणि मीठ घालून मऊ होईपर्यंत प्रेशर कूक करा (3-4 शिट्ट्या).', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'alsande'), 2, 'Grind coconut, red chillies, coriander seeds, and garlic into a paste.', 'नारियल, लाल मिर्च, धनिया और लहसुन का पेस्ट बनाएं।', 'खोबरे, लाल मिरच्या, धणे आणि लसूण वाटून पेस्ट करा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'alsande'), 3, 'Heat oil, sauté sliced onion until soft. Add the coconut paste and fry for 3 minutes.', 'तेल गरम करें, कटा प्याज़ नरम होने तक भूनें। नारियल पेस्ट डालकर 3 मिनट भूनें।', 'तेल गरम करा, कापलेला कांदा मऊ होईपर्यंत परता. नारळाची पेस्ट घालून 3 मिनिटे परता.', 6);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'alsande'), 4, 'Add the cooked black-eyed peas with their cooking liquid and kokum. Simmer for 10 minutes.', 'पकी लोबिया उसके पानी सहित और कोकम डालें। 10 मिनट पकाएं।', 'शिजवलेले अळसांदे त्यांच्या पाण्यासह आणि कोकम घाला. 10 मिनिटे शिजवा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'alsande'), 5, 'Adjust salt and consistency. Serve with steamed rice.', 'नमक और पतलापन ठीक करें। चावल के साथ परोसें।', 'मीठ आणि पातळपणा ठीक करा. भातासोबत वाढा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'patal-bhaji'), 1, 'Wash and chop the greens roughly. Blanch in boiling water for 2 minutes, drain.', 'साग धोकर मोटा-मोटा काटें। उबलते पानी में 2 मिनट डालकर निकालें।', 'पालेभाज्या धुवून जाडसर कापा. उकळत्या पाण्यात 2 मिनिटे घाला, पाणी काढा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'patal-bhaji'), 2, 'Grind coconut, red chillies, and garlic with a little water into a paste.', 'नारियल, लाल मिर्च और लहसुन को थोड़े पानी के साथ पेस्ट बनाएं।', 'खोबरे, लाल मिरच्या आणि लसूण थोड्या पाण्यासह वाटा.', 4);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'patal-bhaji'), 3, 'Heat oil, sauté sliced onion and green chilli until onion is soft. Add turmeric.', 'तेल गरम करें, कटा प्याज़ और हरी मिर्च प्याज़ नरम होने तक भूनें। हल्दी डालें।', 'तेल गरम करा, कापलेला कांदा आणि हिरवी मिरची कांदा मऊ होईपर्यंत परता. हळद घाला.', 4);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'patal-bhaji'), 4, 'Add coconut paste, blanched greens, kokum, salt, and 1.5 cups water. Simmer for 10 minutes.', 'नारियल पेस्ट, उबाला साग, कोकम, नमक और 1.5 कप पानी डालें। 10 मिनट पकाएं।', 'नारळ पेस्ट, ब्लांच केलेल्या भाज्या, कोकम, मीठ आणि 1.5 कप पाणी घाला. 10 मिनिटे शिजवा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'patal-bhaji'), 5, 'The curry should be thin and soupy. Serve with steamed rice.', 'करी पतली और सूपी होनी चाहिए। चावल के साथ परोसें।', 'करी पातळ आणि रस्सेदार असावी. भातासोबत वाढा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'tondak'), 1, 'Soak clams in salted water for 30 minutes to remove sand. Rinse thoroughly.', 'क्लैम को 30 मिनट नमकीन पानी में भिगोएं ताकि रेत निकल जाए। अच्छी तरह धोएं।', 'तिसऱ्या 30 मिनिटे खाऱ्या पाण्यात भिजवा जेणेकरून वाळू निघेल. नीट धुवा.', 32);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'tondak'), 2, 'Grind coconut, red chillies, garlic, cumin, and turmeric into a paste.', 'नारियल, लाल मिर्च, लहसुन, जीरा और हल्दी का पेस्ट बनाएं।', 'खोबरे, लाल मिरच्या, लसूण, जिरे आणि हळद वाटून पेस्ट करा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'tondak'), 3, 'Heat oil, sauté chopped onions until golden. Add the ground masala and fry for 3 minutes.', 'तेल गरम करें, कटे प्याज़ सुनहरे होने तक भूनें। पीसा मसाला डालकर 3 मिनट भूनें।', 'तेल गरम करा, चिरलेला कांदा सोनेरी होईपर्यंत परता. वाटलेला मसाला घालून 3 मिनिटे परता.', 8);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'tondak'), 4, 'Add clams and tamarind. Cover and cook on high heat for 5-7 minutes until all clams open.', 'क्लैम और इमली डालें। ढककर तेज़ आंच पर 5-7 मिनट सब क्लैम खुलने तक पकाएं।', 'तिसऱ्या आणि चिंच घाला. झाकण ठेवून मोठ्या आचेवर 5-7 मिनिटे सर्व तिसऱ्या उघडेपर्यंत शिजवा.', 7);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'tondak'), 5, 'Uncover, toss to coat clams in masala, and cook off excess moisture. Serve hot.', 'ढक्कन खोलें, क्लैम को मसाले में लपेटें, अतिरिक्त पानी सुखाएं। गरमागरम परोसें।', 'झाकण काढा, तिसऱ्या मसाल्यात मिसळा, अतिरिक्त पाणी आटवा. गरम वाढा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'goan-feijoada'), 1, 'Pressure cook soaked kidney beans until soft (5-6 whistles). Reserve beans and cooking water.', 'भीगे राजमा को नरम होने तक प्रेशर कुक करें (5-6 सीटी)। राजमा और पानी अलग रखें।', 'भिजवलेले राजमा मऊ होईपर्यंत प्रेशर कूक करा (5-6 शिट्ट्या). राजमा आणि पाणी बाजूला ठेवा.', 25);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'goan-feijoada'), 2, 'Soak red chillies in vinegar. Grind with garlic, ginger, cumin, cloves, cinnamon, and turmeric into a paste.', 'लाल मिर्च सिरके में भिगोएं। लहसुन, अदरक, जीरा, लौंग, दालचीनी और हल्दी के साथ पेस्ट बनाएं।', 'लाल मिरच्या व्हिनेगरमध्ये भिजवा. लसूण, आले, जिरे, लवंग, दालचिनी आणि हळदीसह पेस्ट वाटा.', 12);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'goan-feijoada'), 3, 'Heat oil, sauté chopped onions until deep brown. Add the masala paste and fry until oil separates.', 'तेल गरम करें, कटे प्याज़ गहरा भूरा होने तक भूनें। मसाला पेस्ट डालकर तेल छूटने तक भूनें।', 'तेल गरम करा, चिरलेला कांदा गडद तपकिरी होईपर्यंत परता. मसाला पेस्ट घालून तेल सुटेपर्यंत परता.', 12);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'goan-feijoada'), 4, 'Add pork ribs and sear on high heat for 5 minutes. Add bean cooking water to cover the meat.', 'पोर्क पसलियां डालें और तेज़ आंच पर 5 मिनट भूनें। मांस डूबने तक राजमा का पानी डालें।', 'डुकराच्या फासळ्या घाला आणि मोठ्या आचेवर 5 मिनिटे परता. मांस बुडेल एवढे राजमा शिजवलेले पाणी घाला.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'goan-feijoada'), 5, 'Cover and simmer on low heat for 45-50 minutes until pork is tender. Add cooked kidney beans.', 'ढककर धीमी आंच पर 45-50 मिनट पोर्क नरम होने तक पकाएं। पके राजमा डालें।', 'झाकण ठेवून मंद आचेवर 45-50 मिनिटे मांस मऊ होईपर्यंत शिजवा. शिजवलेले राजमा घाला.', 50);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'goan-feijoada'), 6, 'Simmer together for 10 minutes. Adjust salt and vinegar. Serve hot with steamed rice or pav.', '10 मिनट साथ में पकाएं। नमक और सिरका ठीक करें। गरमागरम चावल या पाव के साथ परोसें।', '10 मिनिटे एकत्र शिजवा. मीठ आणि व्हिनेगर ठीक करा. गरम भात किंवा पावासोबत वाढा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'idli'), 1, 'Soak rice and dal separately for 4-6 hours, adding fenugreek seeds to the dal.', 'चावल और दाल को अलग-अलग 4-6 घंटे भिगोएं, मेथी दाना दाल में डालें।', 'तांदूळ आणि डाळ वेगवेगळे 4-6 तास भिजवा, मेथी दाणे डाळीत घाला.', 360);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'idli'), 2, 'Grind urad dal first to a smooth fluffy batter, then grind rice to a slightly coarse paste.', 'पहले उड़द दाल को मुलायम और फूला हुआ पीसें, फिर चावल को हल्का दरदरा पीसें।', 'आधी उडीद डाळ मऊ आणि फुलवलेले वाटून घ्या, नंतर तांदूळ किंचित जाडसर वाटा.', 20);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'idli'), 3, 'Mix both batters, add salt, and ferment overnight or 8-10 hours in a warm place.', 'दोनों बैटर मिलाएं, नमक डालें, और 8-10 घंटे गर्म जगह पर खमीर उठने दें।', 'दोन्ही पीठ एकत्र करा, मीठ घाला, आणि 8-10 तास उबदार जागी आंबवा.', 480);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'idli'), 4, 'Grease idli moulds lightly with oil and pour a ladleful of batter into each mould.', 'इडली सांचे में हल्का तेल लगाएं और एक-एक कढ़छी बैटर डालें।', 'इडली साच्यांना हलके तेल लावा आणि प्रत्येक साच्यात एक ओगराळे पीठ घाला.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'idli'), 5, 'Steam in an idli steamer for 10-12 minutes until a toothpick comes out clean.', 'इडली स्टीमर में 10-12 मिनट भाप में पकाएं, टूथपिक साफ निकलनी चाहिए।', 'इडली स्टीमरमध्ये 10-12 मिनिटे वाफवा, टूथपिक स्वच्छ बाहेर यायला हवी.', 12);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'idli'), 6, 'Let cool for a minute, then scoop out with a wet spoon and serve hot with sambar and chutney.', 'एक मिनट ठंडा होने दें, गीले चम्मच से निकालें और सांभर-चटनी के साथ गर्म परोसें।', 'एक मिनिट थंड होऊ द्या, ओल्या चमच्याने काढा आणि सांबार-चटणीसोबत गरम सर्व्ह करा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'masala-dosa'), 1, 'Soak rice and dal separately for 4-6 hours, grind to smooth batter, and ferment overnight.', 'चावल और दाल अलग-अलग 4-6 घंटे भिगोएं, मुलायम पीसें और रात भर खमीर उठने दें।', 'तांदूळ आणि डाळ 4-6 तास भिजवा, मऊ वाटा आणि रात्रभर आंबवा.', 480);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'masala-dosa'), 2, 'Boil potatoes, peel and mash them roughly, keeping some chunks.', 'आलू उबालें, छीलें और मोटा-मोटा मैश करें, कुछ टुकड़े रहने दें।', 'बटाटे उकळा, साल काढा आणि जाडसर कुस्करा, काही तुकडे ठेवा.', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'masala-dosa'), 3, 'Heat oil, splutter mustard seeds, add curry leaves, slit green chillies, and sliced onions. Saute until onions turn translucent.', 'तेल गर्म करें, राई तड़काएं, कड़ी पत्ता, चीरी मिर्च और प्याज़ डालकर प्याज़ पारदर्शी होने तक भूनें।', 'तेल गरम करा, मोहरी तडकवा, कढीपत्ता, चिरलेली मिरची आणि कांदा घालून कांदा पारदर्शक होईपर्यंत परतवा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'masala-dosa'), 4, 'Add turmeric, mashed potatoes, salt, and mix well. Cook for 2 minutes and set aside.', 'हल्दी, मैश आलू, नमक डालकर अच्छी तरह मिलाएं। 2 मिनट पकाकर अलग रखें।', 'हळद, कुस्करलेले बटाटे, मीठ घालून नीट मिसळा. 2 मिनिटे शिजवा आणि बाजूला ठेवा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'masala-dosa'), 5, 'Heat a flat tawa, pour a ladleful of batter and spread in thin circles from the center outward.', 'सपाट तवा गर्म करें, एक कढ़छी बैटर डालें और बीच से बाहर की ओर पतला गोल फैलाएं।', 'सपाट तवा गरम करा, एक ओगराळे पीठ घाला आणि मध्यापासून बाहेरच्या बाजूला पातळ पसरवा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'masala-dosa'), 6, 'Drizzle oil around the edges, cook on medium heat until golden and crispy on the bottom.', 'किनारों पर तेल डालें, मध्यम आंच पर नीचे से सुनहरा और कुरकुरा होने तक पकाएं।', 'कडांवर तेल घाला, मध्यम आचेवर तळाला सोनेरी आणि कुरकुरीत होईपर्यंत शिजवा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'masala-dosa'), 7, 'Place potato masala on one half, fold the dosa over, and serve hot with sambar and chutney.', 'एक तरफ आलू मसाला रखें, डोसा मोड़ें और सांभर-चटनी के साथ गर्म परोसें।', 'एका बाजूला बटाटा मसाला ठेवा, डोसा दुमडा आणि सांबार-चटणीसोबत गरम सर्व्ह करा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'medu-vada'), 1, 'Soak urad dal for 3-4 hours, drain completely and grind to a thick, fluffy batter without adding much water.', 'उड़द दाल 3-4 घंटे भिगोएं, पानी पूरा निकालें और बिना ज़्यादा पानी डाले गाढ़ा फूला हुआ बैटर बनाएं।', 'उडीद डाळ 3-4 तास भिजवा, पाणी पूर्ण निथळून घ्या आणि जास्त पाणी न घालता घट्ट फुलवलेले पीठ वाटा.', 250);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'medu-vada'), 2, 'Add finely chopped onion, green chillies, grated ginger, curry leaves, crushed peppercorns, and salt. Mix well.', 'बारीक कटा प्याज़, हरी मिर्च, कसा अदरक, कड़ी पत्ता, कुटी काली मिर्च और नमक डालकर अच्छी तरह मिलाएं।', 'बारीक चिरलेला कांदा, हिरवी मिरची, किसलेले आले, कढीपत्ता, ठेचलेली मिरी आणि मीठ घालून नीट मिसळा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'medu-vada'), 3, 'Wet your hands, take a lemon-sized ball of batter, shape into a round disc and make a hole in the center with your thumb.', 'हाथ गीला करें, नींबू जितना बैटर लें, गोल चपटा बनाएं और अंगूठे से बीच में छेद करें।', 'हात ओले करा, लिंबाएवढे पीठ घ्या, गोल चपटे करा आणि अंगठ्याने मध्ये भोक पाडा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'medu-vada'), 4, 'Heat oil to 170°C. Gently slide the shaped vadas into the oil, 3-4 at a time.', 'तेल 170°C तक गर्म करें। आकार दिए वड़ों को धीरे से तेल में डालें, एक बार में 3-4।', 'तेल 170°C पर्यंत गरम करा. आकार दिलेले वडे हळूवार तेलात सोडा, एकदा 3-4.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'medu-vada'), 5, 'Fry on medium heat, flipping once, until both sides are deep golden and crispy, about 4-5 minutes.', 'मध्यम आंच पर एक बार पलटकर दोनों तरफ गहरा सुनहरा और कुरकुरा होने तक 4-5 मिनट तलें।', 'मध्यम आचेवर एकदा उलटवून दोन्ही बाजू गडद सोनेरी आणि कुरकुरीत होईपर्यंत 4-5 मिनिटे तळा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'medu-vada'), 6, 'Drain on paper towels and serve hot with coconut chutney and sambar.', 'कागज़ पर तेल निकालें और नारियल चटनी-सांभर के साथ गर्म परोसें।', 'कागदावर तेल निथळवा आणि नारळ चटणी-सांबारसोबत गरम सर्व्ह करा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ven-pongal'), 1, 'Dry roast moong dal until fragrant and lightly golden, then wash rice and dal together.', 'मूंग दाल को सूखा भूनें जब तक खुशबू आए और हल्का सुनहरा हो, फिर चावल-दाल साथ धोएं।', 'मूग डाळ सुवासिक आणि हलकी सोनेरी होईपर्यंत कोरडी भाजा, नंतर तांदूळ-डाळ एकत्र धुवा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ven-pongal'), 2, 'Pressure cook rice and dal with 3.5 cups water and salt for 4-5 whistles until soft and mushy.', 'चावल-दाल को 3.5 कप पानी और नमक के साथ 4-5 सीटी तक कूकर में पकाएं।', 'तांदूळ-डाळ 3.5 कप पाणी आणि मीठ घालून 4-5 शिट्ट्या कुकरमध्ये शिजवा.', 20);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ven-pongal'), 3, 'Mash the cooked rice-dal mixture well with a ladle to get a creamy porridge consistency.', 'पके हुए चावल-दाल को कढ़छी से अच्छी तरह मैश करके दलिये जैसा बनाएं।', 'शिजलेले तांदूळ-डाळ ओगराळ्याने नीट कुस्करून मलईदार कांजीसारखे करा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ven-pongal'), 4, 'Heat ghee in a pan, add crushed peppercorns, cumin seeds, grated ginger, curry leaves, and cashews. Fry until cashews turn golden.', 'कड़ाही में घी गर्म करें, कुटी काली मिर्च, जीरा, कसा अदरक, कड़ी पत्ता और काजू डालें। काजू सुनहरा होने तक भूनें।', 'कढईत तूप गरम करा, ठेचलेली मिरी, जिरे, किसलेले आले, कढीपत्ता आणि काजू घाला. काजू सोनेरी होईपर्यंत परतवा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ven-pongal'), 5, 'Pour the tempering over the mashed pongal, mix well, and serve hot with coconut chutney.', 'तड़का पोंगल पर डालें, अच्छी तरह मिलाएं और नारियल चटनी के साथ गर्म परोसें।', 'फोडणी पोंगलवर ओता, नीट मिसळा आणि नारळ चटणीसोबत गरम सर्व्ह करा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'upma'), 1, 'Dry roast semolina on low heat until slightly aromatic and set aside.', 'सूजी को धीमी आंच पर हल्की खुशबू आने तक सूखा भूनें और अलग रखें।', 'रवा मंद आचेवर हलका सुवासिक होईपर्यंत कोरडा भाजा आणि बाजूला ठेवा.', 4);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'upma'), 2, 'Heat oil, add mustard seeds, urad dal, chana dal, and cashews. Fry until dal turns golden.', 'तेल गर्म करें, राई, उड़द दाल, चना दाल और काजू डालें। दाल सुनहरी होने तक भूनें।', 'तेल गरम करा, मोहरी, उडीद डाळ, हरभरा डाळ आणि काजू घाला. डाळ सोनेरी होईपर्यंत तळा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'upma'), 3, 'Add curry leaves, slit green chillies, grated ginger, and chopped onion. Saute until onion softens.', 'कड़ी पत्ता, चीरी मिर्च, कसा अदरक और कटा प्याज़ डालकर प्याज़ नरम होने तक भूनें।', 'कढीपत्ता, चिरलेली मिरची, किसलेले आले आणि चिरलेला कांदा घालून कांदा मऊ होईपर्यंत परतवा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'upma'), 4, 'Add water and salt, bring to a rolling boil.', 'पानी और नमक डालें, उबाल आने दें।', 'पाणी आणि मीठ घाला, उकळी आणा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'upma'), 5, 'Reduce heat to low, slowly add roasted rava while stirring continuously to avoid lumps.', 'आंच धीमी करें, लगातार चलाते हुए धीरे-धीरे भुना रवा डालें ताकि गांठ न पड़े।', 'आच मंद करा, गुठळ्या होऊ नयेत म्हणून सतत हलवत भाजलेला रवा हळूहळू घाला.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'upma'), 6, 'Cover and cook on low heat for 3-4 minutes until water is absorbed. Squeeze lemon juice, fluff with a fork, and serve hot.', 'ढककर धीमी आंच पर 3-4 मिनट पानी सूखने तक पकाएं। नींबू निचोड़ें, कांटे से फुलाएं और गर्म परोसें।', 'झाकून मंद आचेवर 3-4 मिनिटे पाणी शोषेपर्यंत शिजवा. लिंबू पिळा, काट्याने फुलवा आणि गरम सर्व्ह करा.', 4);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'rava-kesari'), 1, 'Heat 1 tbsp ghee in a pan, roast cashews and raisins until golden. Remove and set aside.', 'कड़ाही में 1 बड़ा चम्मच घी गर्म करें, काजू-किशमिश सुनहरा होने तक भूनें। निकालकर रखें।', 'कढईत 1 चमचा तूप गरम करा, काजू-मनुके सोनेरी होईपर्यंत भाजा. काढून बाजूला ठेवा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'rava-kesari'), 2, 'In the same pan, add remaining ghee and roast semolina on low heat until fragrant.', 'उसी कड़ाही में बचा घी डालें और सूजी को धीमी आंच पर खुशबूदार होने तक भूनें।', 'त्याच कढईत उरलेले तूप घाला आणि रवा मंद आचेवर सुवासिक होईपर्यंत भाजा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'rava-kesari'), 3, 'Boil water separately, add saffron or food colour to it.', 'अलग से पानी उबालें, उसमें रंग या केसर डालें।', 'वेगळे पाणी उकळा, त्यात रंग किंवा केशर घाला.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'rava-kesari'), 4, 'Slowly pour hot water into the roasted rava while stirring continuously to avoid lumps.', 'गर्म पानी धीरे-धीरे भुने रवे में डालें, लगातार चलाते रहें ताकि गांठ न पड़े।', 'गरम पाणी हळूहळू भाजलेल्या रव्यात घाला, गुठळ्या होऊ नयेत म्हणून सतत हलवा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'rava-kesari'), 5, 'Add sugar, mix well, and cook on low heat until the mixture thickens and starts leaving the sides of the pan.', 'चीनी डालें, अच्छी तरह मिलाएं और धीमी आंच पर पकाएं जब तक मिश्रण गाढ़ा होकर कड़ाही छोड़ने लगे।', 'साखर घाला, नीट मिसळा आणि मिश्रण घट्ट होऊन कढईचे कडे सोडेपर्यंत मंद आचेवर शिजवा.', 4);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'rava-kesari'), 6, 'Add cardamom powder and fried cashews-raisins, mix well and serve warm.', 'इलायची पाउडर और भुने काजू-किशमिश डालें, मिलाएं और गर्म परोसें।', 'वेलची पावडर आणि भाजलेले काजू-मनुके घाला, मिसळा आणि गरम सर्व्ह करा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'uttapam'), 1, 'Prepare dosa batter by soaking rice and urad dal, grinding, and fermenting overnight. The batter should be slightly thicker than dosa consistency.', 'चावल-उड़द दाल भिगोकर पीसकर रात भर खमीर उठाएं। बैटर डोसे से थोड़ा गाढ़ा होना चाहिए।', 'तांदूळ-उडीद डाळ भिजवून वाटून रात्रभर आंबवा. पीठ डोशापेक्षा थोडे घट्ट हवे.', 480);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'uttapam'), 2, 'Finely chop onion, tomato, green chillies, and coriander leaves. Keep all toppings ready.', 'प्याज़, टमाटर, हरी मिर्च और धनिया बारीक काटें। सारी टॉपिंग तैयार रखें।', 'कांदा, टोमॅटो, हिरवी मिरची आणि कोथिंबीर बारीक चिरा. सगळे टॉपिंग तयार ठेवा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'uttapam'), 3, 'Heat a thick tawa on medium heat, pour a ladleful of batter and spread into a thick round disc.', 'मोटा तवा मध्यम आंच पर गर्म करें, एक कढ़छी बैटर डालें और मोटा गोल फैलाएं।', 'जाड तवा मध्यम आचेवर गरम करा, एक ओगराळे पीठ घाला आणि जाड गोल पसरवा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'uttapam'), 4, 'Immediately scatter onion, tomato, chillies, carrot, and coriander on top. Gently press the toppings into the batter.', 'तुरंत ऊपर प्याज़, टमाटर, मिर्च, गाजर और धनिया बिखेरें। टॉपिंग हल्के से बैटर में दबाएं।', 'लगेच वर कांदा, टोमॅटो, मिरची, गाजर आणि कोथिंबीर पसरवा. टॉपिंग हलके पिठात दाबा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'uttapam'), 5, 'Drizzle oil around the edges and on top, cover and cook on medium-low heat for 2-3 minutes.', 'किनारों और ऊपर तेल डालें, ढककर मध्यम-धीमी आंच पर 2-3 मिनट पकाएं।', 'कडांवर आणि वर तेल घाला, झाकून मध्यम-मंद आचेवर 2-3 मिनिटे शिजवा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'uttapam'), 6, 'Flip carefully and cook the other side for 1-2 minutes until golden. Serve hot with coconut chutney and sambar.', 'सावधानी से पलटें और दूसरी तरफ 1-2 मिनट सुनहरा होने तक पकाएं। नारियल चटनी-सांभर के साथ गर्म परोसें।', 'काळजीपूर्वक उलटवा आणि दुसरी बाजू 1-2 मिनिटे सोनेरी होईपर्यंत शिजवा. नारळ चटणी-सांबारसोबत गरम सर्व्ह करा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'adai'), 1, 'Soak rice and all four dals together with red chillies for 2-3 hours.', 'चावल और चारों दालों को लाल मिर्च के साथ 2-3 घंटे भिगोएं।', 'तांदूळ आणि चारही डाळी लाल मिरच्यांसोबत 2-3 तास भिजवा.', 180);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'adai'), 2, 'Drain and grind to a coarse, slightly grainy batter. Add salt and asafoetida.', 'पानी निकालकर दरदरा, हल्का दानेदार बैटर बनाएं। नमक और हींग डालें।', 'पाणी निथळवून जाडसर, थोडे दाणेदार पीठ वाटा. मीठ आणि हिंग घाला.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'adai'), 3, 'Mix in finely chopped onion and curry leaves into the batter.', 'बैटर में बारीक कटा प्याज़ और कड़ी पत्ता मिलाएं।', 'पिठात बारीक चिरलेला कांदा आणि कढीपत्ता मिसळा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'adai'), 4, 'Heat a tawa, take a portion of batter and spread into a thick round disc directly on the tawa using wet fingers.', 'तवा गर्म करें, बैटर का हिस्सा लें और गीली उंगलियों से तवे पर मोटा गोल फैलाएं।', 'तवा गरम करा, पीठ घ्या आणि ओल्या बोटांनी तव्यावर जाड गोल पसरवा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'adai'), 5, 'Drizzle sesame oil generously around the edges and on top. Cook on medium heat until the bottom turns crispy and golden.', 'किनारों और ऊपर भरपूर तिल का तेल डालें। मध्यम आंच पर नीचे कुरकुरा सुनहरा होने तक पकाएं।', 'कडांवर आणि वर भरपूर तिळाचे तेल घाला. मध्यम आचेवर तळ कुरकुरीत सोनेरी होईपर्यंत शिजवा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'adai'), 6, 'Flip and cook the other side for 2 minutes. Serve hot with avial, jaggery, or butter.', 'पलटकर दूसरी तरफ 2 मिनट पकाएं। अवियल, गुड़ या मक्खन के साथ गर्म परोसें।', 'उलटवून दुसरी बाजू 2 मिनिटे शिजवा. अवियल, गूळ किंवा लोण्यासोबत गरम सर्व्ह करा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'dal-baati-churma'), 1, 'Knead wheat flour with ghee, carom seeds, and salt into a stiff dough. Shape into round balls.', 'गेहूँ के आटे में घी, अजवाइन और नमक मिलाकर कड़ा आटा गूँधें। गोल बाटी बना लें।', 'गव्हाच्या पिठात तूप, ओवा आणि मीठ घालून कडक पीठ मळा. गोल बाटी तयार करा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'dal-baati-churma'), 2, 'Bake baatis in a preheated oven at 180°C for 30-35 minutes until golden, or roast over coal.', 'बाटी को 180°C ओवन में 30-35 मिनट सुनहरा होने तक सेंकें, या कोयले पर भूनें।', 'बाटी 180°C ओव्हनमध्ये 30-35 मिनिटे सोनेरी होईपर्यंत भाजा, किंवा कोळशावर भाजा.', 35);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'dal-baati-churma'), 3, 'Pressure cook all five dals together with turmeric and salt for 4-5 whistles.', 'सभी पाँचों दालों को हल्दी और नमक के साथ 4-5 सीटी तक प्रेशर कुक करें।', 'सर्व पाच डाळी हळद आणि मीठ घालून 4-5 शिट्ट्या प्रेशर कुक करा.', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'dal-baati-churma'), 4, 'Prepare tempering with ghee, cumin, and red chilli. Pour over mashed dal and simmer.', 'घी में जीरा और लाल मिर्च का तड़का लगाएँ। दाल में डालकर उबालें।', 'तुपात जिरे आणि लाल तिखट घालून फोडणी करा. डाळीत घालून उकळा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'dal-baati-churma'), 5, 'For churma, crush baked baatis coarsely, mix with ghee, jaggery, and cardamom.', 'चूरमे के लिए सेंकी बाटी को मोटा कूटें, घी, गुड़ और इलायची मिलाएँ।', 'चूरम्यासाठी भाजलेली बाटी जाडसर कुटा, तूप, गूळ आणि वेलची मिसळा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'dal-baati-churma'), 6, 'Break remaining baatis, dunk in ghee, and serve with dal and churma on the side.', 'बाकी बाटी तोड़कर घी में डुबोएँ, दाल और चूरमे के साथ परोसें।', 'उरलेली बाटी मोडून तुपात बुडवा, डाळ आणि चूरम्यासोबत वाढा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'gatte-ki-sabzi'), 1, 'Mix besan with carom seeds, turmeric, red chilli, salt, and a little oil. Knead into a stiff dough.', 'बेसन में अजवाइन, हल्दी, लाल मिर्च, नमक और थोड़ा तेल मिलाकर कड़ा आटा गूँधें।', 'बेसनात ओवा, हळद, लाल तिखट, मीठ आणि थोडे तेल मिसळून कडक पीठ मळा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'gatte-ki-sabzi'), 2, 'Roll into long cylindrical strips and boil in water for 15 minutes. Cool and slice into pieces.', 'लंबी बेलनाकार पट्टियाँ बनाएँ और 15 मिनट पानी में उबालें। ठंडा करके टुकड़ों में काटें।', 'लांब गोलाकार पट्ट्या बनवा आणि 15 मिनिटे पाण्यात उकळा. थंड करून तुकडे करा.', 18);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'gatte-ki-sabzi'), 3, 'Heat oil, add cumin, mustard seeds, and asafoetida. Let them splutter.', 'तेल गरम करें, जीरा, राई और हींग का तड़का लगाएँ।', 'तेल गरम करा, जिरे, मोहरी आणि हिंग घालून फोडणी करा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'gatte-ki-sabzi'), 4, 'Whisk yogurt with besan water, coriander powder, and turmeric. Add to the tempering and cook on low.', 'दही को बेसन के पानी, धनिया पाउडर और हल्दी के साथ फेंटें। तड़के में डालकर धीमी आँच पर पकाएँ।', 'दही बेसनाच्या पाण्यात, धणे पूड आणि हळदीसोबत फेटा. फोडणीत घालून मंद आचेवर शिजवा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'gatte-ki-sabzi'), 5, 'Add sliced gatte to the gravy and simmer for 5-7 minutes. Garnish with coriander.', 'कटे हुए गट्टे ग्रेवी में डालें और 5-7 मिनट उबालें। धनिये से सजाएँ।', 'कापलेले गट्टे ग्रेव्हीत घाला आणि 5-7 मिनिटे उकळा. कोथिंबीर घालून वाढा.', 7);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ker-sangri'), 1, 'Soak ker and sangri separately in water overnight. Drain, wash, and boil until tender.', 'केर और सांगरी को रात भर अलग-अलग पानी में भिगोएँ। धोकर नरम होने तक उबालें।', 'केर आणि सांगरी रात्रभर वेगवेगळ्या पाण्यात भिजवा. धुवून मऊ होईपर्यंत उकळा.', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ker-sangri'), 2, 'Heat mustard oil until smoking, let it cool slightly. Add cumin, mustard seeds, and dried red chillies.', 'सरसों का तेल धुआँ आने तक गरम करें, थोड़ा ठंडा होने दें। जीरा, राई और सूखी लाल मिर्च डालें।', 'मोहरीचे तेल धूर येईपर्यंत गरम करा, थोडे थंड करा. जिरे, मोहरी आणि सुक्या लाल मिरच्या घाला.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ker-sangri'), 3, 'Add boiled ker-sangri to the oil. Stir well on medium heat.', 'उबली हुई केर-सांगरी तेल में डालें। मध्यम आँच पर अच्छे से भूनें।', 'उकळलेली केर-सांगरी तेलात घाला. मध्यम आचेवर चांगले परतून घ्या.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ker-sangri'), 4, 'Add turmeric, coriander powder, red chilli, and salt. Mix and cook for 5 minutes.', 'हल्दी, धनिया पाउडर, लाल मिर्च और नमक डालें। मिलाकर 5 मिनट पकाएँ।', 'हळद, धणे पूड, लाल तिखट आणि मीठ घाला. मिसळून 5 मिनिटे शिजवा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'ker-sangri'), 5, 'Sprinkle amchur, toss well. Serve hot with bajre ki roti.', 'अमचूर छिड़कें, अच्छे से मिलाएँ। बाजरे की रोटी के साथ गरम परोसें।', 'आमचूर भुरभुरा, चांगले मिसळा. बाजरीच्या भाकरीसोबत गरम वाढा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'pyaaz-kachori'), 1, 'Make a smooth dough with maida, ghee, and salt. Rest for 20 minutes covered.', 'मैदा, घी और नमक से मुलायम आटा गूँधें। 20 मिनट ढककर रखें।', 'मैदा, तूप आणि मीठ घालून मऊ पीठ मळा. 20 मिनिटे झाकून ठेवा.', 25);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'pyaaz-kachori'), 2, 'Heat oil, sauté onions until golden. Add all spices and cook until dry. Cool the filling.', 'तेल गरम करें, प्याज़ सुनहरा होने तक भूनें। सभी मसाले डालकर सूखा भूनें। भरावन ठंडा करें।', 'तेल गरम करा, कांदा सोनेरी होईपर्यंत परता. सर्व मसाले घालून कोरडे परता. सारण थंड करा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'pyaaz-kachori'), 3, 'Divide dough into balls, roll out, fill with onion mixture, and seal tightly into round shape.', 'आटे के पेड़े बनाएँ, बेलें, प्याज़ का भरावन भरें और गोल आकार में बंद करें।', 'पिठाचे गोळे करा, लाटा, कांद्याचे सारण भरा आणि गोलाकार बंद करा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'pyaaz-kachori'), 4, 'Deep fry on low-medium heat until golden and crisp, flipping occasionally.', 'धीमी-मध्यम आँच पर सुनहरा और करारा होने तक तलें, बीच-बीच में पलटते रहें।', 'मंद-मध्यम आचेवर सोनेरी आणि खुसखुशीत होईपर्यंत तळा, मधूनमधून उलटा.', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'pyaaz-kachori'), 5, 'Drain on paper towels. Serve hot with tamarind and green chutney.', 'कागज़ पर निकालें। इमली और हरी चटनी के साथ गरम परोसें।', 'कागदावर काढा. चिंचेची आणि हिरवी चटणी सोबत गरम वाढा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'laal-maas'), 1, 'Soak Mathania chillies in warm water for 20 minutes. Grind to a smooth paste.', 'मथानिया मिर्च को गरम पानी में 20 मिनट भिगोएँ। महीन पीस लें।', 'मथानिया मिरच्या गरम पाण्यात 20 मिनिटे भिजवा. बारीक वाटून घ्या.', 25);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'laal-maas'), 2, 'Heat mustard oil until smoking. Add bay leaf, cloves, cumin, and sauté sliced onions until deep brown.', 'सरसों का तेल धुआँ आने तक गरम करें। तेज पत्ता, लौंग, जीरा डालें और प्याज़ गहरा भूरा होने तक भूनें।', 'मोहरीचे तेल धूर येईपर्यंत गरम करा. तमालपत्र, लवंग, जिरे घाला आणि कांदा गडद तपकिरी होईपर्यंत परता.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'laal-maas'), 3, 'Add garlic paste and mutton pieces. Sear on high heat for 5 minutes.', 'लहसुन का पेस्ट और मटन के टुकड़े डालें। तेज़ आँच पर 5 मिनट भूनें।', 'लसूण पेस्ट आणि मटणाचे तुकडे घाला. तीव्र आचेवर 5 मिनिटे परता.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'laal-maas'), 4, 'Add chilli paste, coriander powder, and whisked yogurt. Mix well.', 'मिर्च का पेस्ट, धनिया पाउडर और फेंटा दही डालें। अच्छे से मिलाएँ।', 'मिरची पेस्ट, धणे पूड आणि फेटलेले दही घाला. चांगले मिसळा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'laal-maas'), 5, 'Add water, cover, and slow-cook until mutton is tender and oil separates, about 45 minutes.', 'पानी डालें, ढककर धीमी आँच पर मटन गलने और तेल छूटने तक पकाएँ, लगभग 45 मिनट।', 'पाणी घाला, झाकून मंद आचेवर मटण मऊ होईपर्यंत आणि तेल सुटेपर्यंत शिजवा, सुमारे 45 मिनिटे.', 45);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'safed-maas'), 1, 'Soak cashews and poppy seeds in warm water for 30 minutes. Grind into a fine paste.', 'काजू और खसखस को 30 मिनट गरम पानी में भिगोएँ। महीन पेस्ट बना लें।', 'काजू आणि खसखस 30 मिनिटे गरम पाण्यात भिजवा. बारीक पेस्ट करा.', 35);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'safed-maas'), 2, 'Heat ghee, add cardamom and mace. Sauté onions until soft and translucent — do not brown.', 'घी गरम करें, इलायची और जावित्री डालें। प्याज़ को नरम और पारदर्शी होने तक भूनें — भूरा न करें।', 'तूप गरम करा, वेलची आणि जायपत्री घाला. कांदा मऊ आणि पारदर्शक होईपर्यंत परता — तपकिरी करू नका.', 8);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'safed-maas'), 3, 'Add mutton pieces and seal on medium heat without browning. Add whisked yogurt gradually.', 'मटन डालें और मध्यम आँच पर बिना भूरा किए सील करें। फेंटा दही धीरे-धीरे डालें।', 'मटण घाला आणि मध्यम आचेवर तपकिरी न करता सील करा. फेटलेले दही हळूहळू घाला.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'safed-maas'), 4, 'Add cashew-poppy paste, white pepper, salt, and water. Cover and cook on low until tender.', 'काजू-खसखस पेस्ट, सफ़ेद मिर्च, नमक और पानी डालें। ढककर धीमी आँच पर गलने तक पकाएँ।', 'काजू-खसखस पेस्ट, पांढरी मिरी, मीठ आणि पाणी घाला. झाकून मंद आचेवर मऊ होईपर्यंत शिजवा.', 45);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'safed-maas'), 5, 'Stir in cream, simmer for 5 minutes. Serve garnished with slivered almonds.', 'मलाई मिलाएँ, 5 मिनट उबालें। बादाम की कतरन से सजाकर परोसें।', 'साय घालून मिसळा, 5 मिनिटे उकळा. बदामाच्या काप्यांनी सजवून वाढा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'papad-ki-sabzi'), 1, 'Break papads into small pieces. Roast or fry lightly and set aside.', 'पापड़ को छोटे टुकड़ों में तोड़ लें। हल्का भून या तल कर अलग रखें।', 'पापड लहान तुकड्यांत मोडा. हलके भाजा किंवा तळा आणि बाजूला ठेवा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'papad-ki-sabzi'), 2, 'Heat oil, add cumin, mustard seeds, and asafoetida. Let them splutter.', 'तेल गरम करें, जीरा, राई और हींग डालकर चटकने दें।', 'तेल गरम करा, जिरे, मोहरी आणि हिंग घालून तडतडू द्या.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'papad-ki-sabzi'), 3, 'Whisk yogurt with turmeric, coriander powder, red chilli, and a cup of water. Pour into the pan.', 'दही को हल्दी, धनिया पाउडर, लाल मिर्च और एक कप पानी से फेंटें। कढ़ाई में डालें।', 'दही हळद, धणे पूड, लाल तिखट आणि एक कप पाण्यासोबत फेटा. कढईत घाला.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'papad-ki-sabzi'), 4, 'Bring to a boil, add papad pieces, and simmer for 5 minutes until gravy thickens slightly.', 'उबाल आने दें, पापड़ के टुकड़े डालें और 5 मिनट ग्रेवी गाढ़ी होने तक पकाएँ।', 'उकळी आणा, पापडाचे तुकडे घाला आणि 5 मिनिटे ग्रेव्ही थोडी घट्ट होईपर्यंत शिजवा.', 6);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'papad-ki-sabzi'), 5, 'Garnish with fresh coriander and serve with steamed rice or roti.', 'हरे धनिये से सजाएँ और चावल या रोटी के साथ परोसें।', 'कोथिंबीर घालून भात किंवा पोळीसोबत वाढा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'bajre-ki-roti'), 1, 'Mix bajra flour with salt. Add warm water gradually and knead into a soft dough.', 'बाजरे के आटे में नमक मिलाएँ। गरम पानी डालकर नरम आटा गूँधें।', 'बाजरीच्या पिठात मीठ मिसळा. गरम पाणी घालून मऊ पीठ मळा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'bajre-ki-roti'), 2, 'Take a ball of dough, pat it flat between your palms or on a plastic sheet — do not use a rolling pin.', 'आटे का पेड़ा लें, हथेली या प्लास्टिक शीट पर थपथपाकर रोटी बनाएँ — बेलन का उपयोग न करें।', 'पिठाचा गोळा घ्या, तळहातावर किंवा प्लास्टिक शीटवर थापून भाकरी बनवा — लाटणे वापरू नका.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'bajre-ki-roti'), 3, 'Roast on a hot tawa on both sides until brown spots appear.', 'गरम तवे पर दोनों तरफ़ भूरे धब्बे आने तक सेंकें।', 'गरम तव्यावर दोन्ही बाजूंनी तपकिरी डाग येईपर्यंत भाजा.', 4);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'bajre-ki-roti'), 4, 'Place directly on flame to puff up and get charred spots.', 'सीधे आँच पर रखकर फुलाएँ और भूरी चित्ती लगने दें।', 'थेट आचेवर ठेवून फुगवा आणि भाजके डाग लागू द्या.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'bajre-ki-roti'), 5, 'Apply generous ghee or white butter and serve with jaggery or laal maas.', 'ऊपर भरपूर घी या सफ़ेद मक्खन लगाएँ। गुड़ या लाल मांस के साथ परोसें।', 'भरपूर तूप किंवा पांढरे लोणी लावा. गूळ किंवा लाल मांसासोबत वाढा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'besan-gatte'), 1, 'Mix besan with carom seeds, turmeric, chilli powder, salt, and 1 tbsp oil. Knead into stiff dough with minimal water.', 'बेसन में अजवाइन, हल्दी, मिर्च, नमक और 1 चम्मच तेल मिलाएँ। कम पानी से कड़ा आटा गूँधें।', 'बेसनात ओवा, हळद, तिखट, मीठ आणि 1 चमचा तेल मिसळा. कमी पाण्याने कडक पीठ मळा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'besan-gatte'), 2, 'Roll into thin long cylinders and boil in water for 12-15 minutes. Drain and cut into 1-inch pieces.', 'पतली लंबी लाठी बनाएँ और 12-15 मिनट उबालें। छानकर 1 इंच के टुकड़े काटें।', 'पातळ लांब दांड्या बनवा आणि 12-15 मिनिटे उकळा. गाळून 1 इंचाचे तुकडे करा.', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'besan-gatte'), 3, 'Heat oil, add cumin, asafoetida. Add gatte pieces and sauté for 3-4 minutes.', 'तेल गरम करें, जीरा और हींग डालें। गट्टे डालकर 3-4 मिनट भूनें।', 'तेल गरम करा, जिरे आणि हिंग घाला. गट्टे घालून 3-4 मिनिटे परता.', 4);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'besan-gatte'), 4, 'Add coriander powder and remaining spices. Toss until well coated.', 'धनिया पाउडर और बाकी मसाले डालें। अच्छे से मिलाएँ।', 'धणे पूड आणि उरलेले मसाले घाला. चांगले मिसळा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'besan-gatte'), 5, 'Garnish with coriander and serve as a side dish.', 'धनिये से सजाएँ और साइड डिश के रूप में परोसें।', 'कोथिंबीर घालून बाजूच्या पदार्थ म्हणून वाढा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mogar-dal'), 1, 'Wash moong dal and pressure cook with turmeric, salt, and 2.5 cups water for 3 whistles.', 'मूँग दाल धोकर हल्दी, नमक और 2.5 कप पानी के साथ 3 सीटी प्रेशर कुक करें।', 'मूग डाळ धुवून हळद, मीठ आणि 2.5 कप पाण्यासोबत 3 शिट्ट्या प्रेशर कुक करा.', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mogar-dal'), 2, 'Mash lightly with a ladle. Adjust water for desired consistency.', 'कलछी से हल्का मैश करें। मनचाही गाढ़ेपन के लिए पानी मिलाएँ।', 'उलथन्याने हलके मॅश करा. हवी तशी घट्टपणासाठी पाणी मिसळा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mogar-dal'), 3, 'Heat ghee in a small pan, add cumin, dried red chillies, asafoetida, and green chilli.', 'छोटी कढ़ाई में घी गरम करें, जीरा, सूखी लाल मिर्च, हींग और हरी मिर्च डालें।', 'लहान कढईत तूप गरम करा, जिरे, सुक्या लाल मिरच्या, हिंग आणि हिरवी मिरची घाला.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mogar-dal'), 4, 'Pour the tempering over the dal. Stir well and simmer for 2 minutes.', 'तड़का दाल पर डालें। अच्छे से मिलाकर 2 मिनट उबालें।', 'फोडणी डाळीवर ओता. चांगले मिसळून 2 मिनिटे उकळा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mogar-dal'), 5, 'Garnish with fresh coriander and serve with steamed rice or bajre ki roti.', 'हरे धनिये से सजाएँ और चावल या बाजरे की रोटी के साथ परोसें।', 'कोथिंबीर घालून भात किंवा बाजरीच्या भाकरीसोबत वाढा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'panchkuta'), 1, 'Soak all dried ingredients separately overnight. Drain and boil each until tender.', 'सभी सूखी सामग्री अलग-अलग रात भर भिगोएँ। छानकर नरम होने तक उबालें।', 'सर्व सुके पदार्थ वेगवेगळे रात्रभर भिजवा. गाळून मऊ होईपर्यंत उकळा.', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'panchkuta'), 2, 'Heat mustard oil until smoking point, cool slightly. Add cumin seeds.', 'सरसों का तेल धुआँ आने तक गरम करें, थोड़ा ठंडा करें। जीरा डालें।', 'मोहरीचे तेल धूर येईपर्यंत गरम करा, थोडे थंड करा. जिरे घाला.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'panchkuta'), 3, 'Add all boiled ingredients and stir-fry on medium heat for 5 minutes.', 'सभी उबली सामग्री डालकर मध्यम आँच पर 5 मिनट भूनें।', 'सर्व उकळलेले पदार्थ घालून मध्यम आचेवर 5 मिनिटे परता.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'panchkuta'), 4, 'Add turmeric, red chilli, coriander powder, and salt. Mix and cook covered for 10 minutes.', 'हल्दी, लाल मिर्च, धनिया पाउडर और नमक डालें। मिलाकर ढककर 10 मिनट पकाएँ।', 'हळद, लाल तिखट, धणे पूड आणि मीठ घाला. मिसळून झाकून 10 मिनिटे शिजवा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'panchkuta'), 5, 'Add amchur, toss well, and serve hot with bajre ki roti.', 'अमचूर डालें, अच्छे से मिलाएँ और बाजरे की रोटी के साथ गरम परोसें।', 'आमचूर घाला, चांगले मिसळा आणि बाजरीच्या भाकरीसोबत गरम वाढा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chakki-ki-sabzi'), 1, 'Knead wheat flour with salt and water into a medium-stiff dough. Pinch small pieces and flatten into discs.', 'गेहूँ के आटे में नमक-पानी से आटा गूँधें। छोटे टुकड़े तोड़कर चपटी लोइयाँ बनाएँ।', 'गव्हाच्या पिठात मीठ-पाणी घालून पीठ मळा. छोटे तुकडे मोडून चपट्या लोया बनवा.', 7);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chakki-ki-sabzi'), 2, 'Boil the dough discs in water for 8 minutes. Drain and set aside.', 'लोइयों को पानी में 8 मिनट उबालें। छानकर अलग रखें।', 'लोया पाण्यात 8 मिनिटे उकळा. गाळून बाजूला ठेवा.', 8);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chakki-ki-sabzi'), 3, 'Heat oil, add cumin. Sauté onion until golden, add tomato and cook until soft.', 'तेल गरम करें, जीरा डालें। प्याज़ सुनहरा होने तक भूनें, टमाटर डालकर नरम होने तक पकाएँ।', 'तेल गरम करा, जिरे घाला. कांदा सोनेरी होईपर्यंत परता, टोमॅटो घालून मऊ होईपर्यंत शिजवा.', 7);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chakki-ki-sabzi'), 4, 'Add all spices and water to make a medium gravy. Add boiled discs and simmer for 5 minutes.', 'सभी मसाले और पानी डालकर मध्यम ग्रेवी बनाएँ। उबली लोइयाँ डालें और 5 मिनट पकाएँ।', 'सर्व मसाले आणि पाणी घालून मध्यम ग्रेव्ही बनवा. उकळलेल्या लोया घालून 5 मिनिटे शिजवा.', 6);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'chakki-ki-sabzi'), 5, 'Garnish with coriander and serve hot with roti.', 'धनिये से सजाकर रोटी के साथ गरम परोसें।', 'कोथिंबीर घालून पोळीसोबत गरम वाढा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'raabdi'), 1, 'Mix bajra flour with water to make a smooth lump-free slurry.', 'बाजरे के आटे को पानी में गाँठ रहित घोल बना लें।', 'बाजरीचे पीठ पाण्यात गुठळ्या न राहतील असे मिसळा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'raabdi'), 2, 'Bring buttermilk to a simmer in a heavy-bottomed pan. Stir continuously to prevent curdling.', 'भारी तले की कढ़ाई में छाछ को धीमी आँच पर गरम करें। लगातार चलाते रहें।', 'जड बुडाच्या भांड्यात ताक मंद आचेवर गरम करा. सतत हलवत राहा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'raabdi'), 3, 'Slowly add the bajra slurry to simmering buttermilk, stirring constantly. Cook until thick.', 'बाजरे का घोल धीरे-धीरे उबलती छाछ में डालें, लगातार चलाते रहें। गाढ़ा होने तक पकाएँ।', 'बाजरीचे मिश्रण हळूहळू उकळत्या ताकात घाला, सतत हलवा. घट्ट होईपर्यंत शिजवा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'raabdi'), 4, 'Add salt, green chilli, and cumin. Stir well and cook for 2 more minutes.', 'नमक, हरी मिर्च और जीरा डालें। अच्छे से मिलाकर 2 मिनट और पकाएँ।', 'मीठ, हिरवी मिरची आणि जिरे घाला. चांगले मिसळून 2 मिनिटे अजून शिजवा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'raabdi'), 5, 'Serve hot with a dollop of ghee. Can be eaten as is or with bajre ki roti.', 'ऊपर घी डालकर गरम परोसें। ऐसे ही या बाजरे की रोटी के साथ खाएँ।', 'वर तूप घालून गरम वाढा. असेच खा किंवा बाजरीच्या भाकरीसोबत.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'bajra-khichdi'), 1, 'Wash bajra and moong dal together. Soak for 30 minutes and drain.', 'बाजरा और मूँग दाल एक साथ धोएँ। 30 मिनट भिगोकर छान लें।', 'बाजरी आणि मूग डाळ एकत्र धुवा. 30 मिनिटे भिजवून गाळा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'bajra-khichdi'), 2, 'Heat ghee, add cumin seeds, ginger, and green chillies. Sauté for a minute.', 'घी गरम करें, जीरा, अदरक और हरी मिर्च डालकर एक मिनट भूनें।', 'तूप गरम करा, जिरे, आले आणि हिरवी मिरची घालून एक मिनिट परता.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'bajra-khichdi'), 3, 'Add soaked bajra-dal, turmeric, salt, and 4 cups water. Pressure cook for 5-6 whistles.', 'भिगोया बाजरा-दाल, हल्दी, नमक और 4 कप पानी डालें। 5-6 सीटी प्रेशर कुक करें।', 'भिजवलेली बाजरी-डाळ, हळद, मीठ आणि 4 कप पाणी घाला. 5-6 शिट्ट्या प्रेशर कुक करा.', 20);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'bajra-khichdi'), 4, 'Open, mash lightly, and adjust consistency. Add more ghee on top.', 'खोलें, हल्का मैश करें और गाढ़ापन ठीक करें। ऊपर और घी डालें।', 'उघडा, हलके मॅश करा आणि घट्टपणा ठीक करा. वर अजून तूप घाला.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'bajra-khichdi'), 5, 'Serve hot with a generous pour of ghee and a glass of cold buttermilk.', 'भरपूर घी और ठंडी छाछ के साथ गरम परोसें।', 'भरपूर तूप आणि थंड ताकासोबत गरम वाढा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'lehsun-ki-chutney'), 1, 'Dry roast garlic cloves on a tawa until they turn slightly charred and soft.', 'तवे पर लहसुन की कलियों को हल्का जलने और नरम होने तक सूखा भूनें।', 'तव्यावर लसूण पाकळ्या हलक्या करपेपर्यंत आणि मऊ होईपर्यंत कोरड्या भाजा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'lehsun-ki-chutney'), 2, 'Dry roast dried red chillies and cumin seeds separately until fragrant.', 'सूखी लाल मिर्च और जीरा अलग-अलग खुशबू आने तक सूखा भूनें।', 'सुक्या लाल मिरच्या आणि जिरे वेगवेगळे सुवास येईपर्यंत कोरडे भाजा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'lehsun-ki-chutney'), 3, 'Crush everything together in a mortar-pestle to a coarse paste. Add salt.', 'सिल-बट्टे या खल-मूसल में सब कूटकर दरदरा पेस्ट बनाएँ। नमक डालें।', 'खलबत्त्यात सर्व एकत्र कुटून जाडसर पेस्ट करा. मीठ घाला.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'lehsun-ki-chutney'), 4, 'Mix in mustard oil and lemon juice. Adjust salt and heat.', 'सरसों का तेल और नींबू का रस मिलाएँ। नमक और तीखापन ठीक करें।', 'मोहरीचे तेल आणि लिंबाचा रस मिसळा. मीठ आणि तिखटपणा ठीक करा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'lehsun-ki-chutney'), 5, 'Serve as accompaniment with dal-baati, bajre ki roti, or any Rajasthani meal.', 'दाल-बाटी, बाजरे की रोटी या किसी भी राजस्थानी खाने के साथ परोसें।', 'दाल-बाटी, बाजरीची भाकरी किंवा कोणत्याही राजस्थानी जेवणासोबत वाढा.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'bikaneri-bhujia'), 1, 'Mix besan, moth flour, all spices, salt, baking soda, and 2 tbsp hot oil. Knead into a smooth dough with water.', 'बेसन, मोठ आटा, सभी मसाले, नमक, सोडा और 2 चम्मच गरम तेल मिलाएँ। पानी से मुलायम आटा गूँधें।', 'बेसन, मटकी पीठ, सर्व मसाले, मीठ, सोडा आणि 2 चमचे गरम तेल मिसळा. पाण्याने मऊ पीठ मळा.', 10);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'bikaneri-bhujia'), 2, 'Fill the bhujia press (sev maker) with fine-hole disc. Heat oil for deep frying.', 'भुजिया प्रेस (सेव मेकर) में बारीक छेद वाली जाली लगाएँ। तेल तलने के लिए गरम करें।', 'भुजिया प्रेसमध्ये (शेव मेकर) बारीक छिद्रांची जाळी लावा. तेल तळण्यासाठी गरम करा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'bikaneri-bhujia'), 3, 'Press dough directly into medium-hot oil in circular motion. Fry until golden and crisp.', 'आटे को मध्यम गरम तेल में गोलाकार घुमाते हुए दबाएँ। सुनहरा और कुरकुरा होने तक तलें।', 'पीठ मध्यम गरम तेलात गोलाकार फिरवत दाबा. सोनेरी आणि कुरकुरीत होईपर्यंत तळा.', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'bikaneri-bhujia'), 4, 'Remove with slotted spoon, drain on paper. Repeat with remaining dough.', 'छन्नी से निकालें, कागज़ पर रखें। बचे आटे से दोहराएँ।', 'चमच्याने काढा, कागदावर ठेवा. उरलेल्या पिठाने पुन्हा करा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'bikaneri-bhujia'), 5, 'Cool completely and break into pieces. Store in an airtight container.', 'पूरा ठंडा करें और टुकड़ों में तोड़ें। एयरटाइट डिब्बे में रखें।', 'पूर्ण थंड करा आणि तुकड्यांत मोडा. हवाबंद डब्यात ठेवा.', 2);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mohan-maas'), 1, 'Soak saffron in 2 tbsp warm milk. Soak cashews and almonds in water, then grind to paste.', 'केसर को 2 चम्मच गरम दूध में भिगोएँ। काजू-बादाम भिगोकर पेस्ट बनाएँ।', 'केशर 2 चमचे गरम दुधात भिजवा. काजू-बदाम भिजवून पेस्ट करा.', 15);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mohan-maas'), 2, 'Heat ghee, add cardamom, mace, and whole red chillies. Sauté onions until golden.', 'घी गरम करें, इलायची, जावित्री और साबुत लाल मिर्च डालें। प्याज़ सुनहरा होने तक भूनें।', 'तूप गरम करा, वेलची, जायपत्री आणि साबूत लाल मिरच्या घाला. कांदा सोनेरी होईपर्यंत परता.', 8);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mohan-maas'), 3, 'Add mutton and sear on high heat until well browned on all sides.', 'मटन डालकर तेज़ आँच पर चारों तरफ़ अच्छे से भूनें।', 'मटण घालून तीव्र आचेवर सर्व बाजूंनी चांगले परता.', 8);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mohan-maas'), 4, 'Add milk, nut paste, salt, and saffron milk. Cover and slow-cook until mutton is tender.', 'दूध, मेवा पेस्ट, नमक और केसर वाला दूध डालें। ढककर मटन गलने तक धीमी आँच पर पकाएँ।', 'दूध, मेव्यांची पेस्ट, मीठ आणि केशर दूध घाला. झाकून मटण मऊ होईपर्यंत मंद आचेवर शिजवा.', 45);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'mohan-maas'), 5, 'Stir in cream, simmer for 5 more minutes. Garnish with slivered almonds and serve.', 'मलाई मिलाएँ, 5 मिनट और उबालें। बादाम की कतरन से सजाकर परोसें।', 'साय घालून मिसळा, 5 मिनिटे अजून उकळा. बदामाच्या काप्यांनी सजवून वाढा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'jungli-maas'), 1, 'Heat generous ghee in a heavy-bottomed pot until very hot.', 'भारी तले की हांडी में भरपूर घी बहुत गरम करें।', 'जड बुडाच्या भांड्यात भरपूर तूप खूप गरम करा.', 3);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'jungli-maas'), 2, 'Break dried red chillies and add to hot ghee with crushed garlic. Sauté for 30 seconds.', 'सूखी लाल मिर्च तोड़कर गरम घी में कुटे लहसुन के साथ डालें। 30 सेकंड भूनें।', 'सुक्या लाल मिरच्या मोडून गरम तुपात ठेचलेल्या लसणासोबत घाला. 30 सेकंद परता.', 1);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'jungli-maas'), 3, 'Add mutton pieces and salt. Sear on high heat for 5 minutes, stirring occasionally.', 'मटन और नमक डालें। तेज़ आँच पर 5 मिनट भूनें, बीच-बीच में हिलाएँ।', 'मटण आणि मीठ घाला. तीव्र आचेवर 5 मिनिटे परता, मधूनमधून हलवा.', 5);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'jungli-maas'), 4, 'Add water, cover tightly, and cook on low heat until mutton is fall-off-the-bone tender.', 'पानी डालें, कसकर ढकें और धीमी आँच पर मटन हड्डी से गिरने लगे तब तक पकाएँ।', 'पाणी घाला, घट्ट झाकून मंद आचेवर मटण हाडापासून सुटेपर्यंत शिजवा.', 45);
INSERT INTO recipe_steps (dish_id, step_number, instruction_en, instruction_hi, instruction_mr, duration_min) VALUES ((SELECT id FROM dishes WHERE slug = 'jungli-maas'), 5, 'Uncover, increase heat to reduce any excess liquid. Serve with roti and raw onion.', 'ढक्कन खोलें, तेज़ आँच पर अतिरिक्त पानी सुखाएँ। रोटी और कच्चे प्याज़ के साथ परोसें।', 'झाकण उघडा, तीव्र आचेवर जास्तीचे पाणी आटवा. पोळी आणि कच्च्या कांद्यासोबत वाढा.', 5);